def distinct_counts_in_windows(nums, k):
 counts={};answer=[]
 for index,value in enumerate(nums):
  counts[value]=counts.get(value,0)+1
  if index>=k:
   old=nums[index-k];counts[old]-=1
   if counts[old]==0:del counts[old]
  if index>=k-1:answer.append(len(counts))
 return answer

